<script setup lang="ts">
interface CalendarEvent {date:string;end?:string;title:string;type:'RENEWAL'|'ACTIVITY'|'INTENTION'}
const props=defineProps<{events:CalendarEvent[]}>()
const cursor=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1)),selected=ref(new Date()),filter=ref('ALL')
const labels:Record<string,string>={ALL:'All events',ACTIVITY:'Activities',RENEWAL:'Renewals',INTENTION:'Planned starts'}
const events=computed(()=>props.events.filter(e=>filter.value==='ALL'||e.type===filter.value))
const cells=computed(()=>{const first=new Date(cursor.value),offset=(first.getDay()+6)%7;return Array.from({length:42},(_,i)=>new Date(first.getFullYear(),first.getMonth(),1-offset+i))})
function onDay(day:Date){return events.value.filter(e=>{const start=new Date(e.date),end=new Date(e.end||e.date);start.setHours(0,0,0,0);end.setHours(23,59,59,999);return day>=start&&day<=end})}
const selectedEvents=computed(()=>onDay(selected.value))
function move(n:number){cursor.value=new Date(cursor.value.getFullYear(),cursor.value.getMonth()+n,1)}
const color=(type:string)=>type==='ACTIVITY'?'calendar-activity':type==='RENEWAL'?'calendar-renewal':'calendar-intention'
</script>
<template>
 <div class="activity-calendar">
  <header class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-semibold">{{cursor.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}}</h2><div class="flex gap-1"><UButton color="neutral" variant="ghost" icon="i-lucide-chevron-left" aria-label="Previous month" @click="move(-1)"/><UButton color="neutral" variant="outline" @click="cursor=new Date(new Date().getFullYear(),new Date().getMonth(),1);selected=new Date()">Today</UButton><UButton color="neutral" variant="ghost" icon="i-lucide-chevron-right" aria-label="Next month" @click="move(1)"/></div></header>
  <nav class="flex flex-wrap gap-1 my-4" aria-label="Calendar event types"><UButton v-for="(label,key) in labels" :key="key" size="sm" :color="filter===key?'primary':'neutral'" :variant="filter===key?'soft':'ghost'" @click="filter=String(key)">{{label}}</UButton></nav>
  <div class="calendar-grid"><span v-for="day in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']" :key="day" class="calendar-weekday">{{day}}</span><button v-for="day in cells" :key="day.toISOString()" class="calendar-cell" :class="{'calendar-outside':day.getMonth()!==cursor.getMonth(),'calendar-selected':day.toDateString()===selected.toDateString()}" :aria-label="day.toLocaleDateString('en-IN',{dateStyle:'full'})+', '+onDay(day).length+' events'" :aria-pressed="day.toDateString()===selected.toDateString()" @click="selected=day"><span class="calendar-date" :class="{'calendar-today':day.toDateString()===new Date().toDateString()}">{{day.getDate()}}</span><span v-for="(event,i) in onDay(day).slice(0,3)" :key="i" class="calendar-event" :class="color(event.type)">{{event.title}}</span><span v-if="onDay(day).length>3" class="text-xs text-muted">+{{onDay(day).length-3}} more</span></button></div>
  <div class="mt-5 border-t border-default pt-4"><h3 class="font-semibold text-sm">{{selected.toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}}</h3><div v-for="(event,i) in selectedEvents" :key="i" class="flex flex-wrap items-center gap-3 py-3 border-b border-default"><span class="calendar-event" :class="color(event.type)">{{labels[event.type]}}</span><span class="text-sm">{{event.title}}</span></div><p v-if="!selectedEvents.length" class="text-sm text-muted py-4">No events on this day.</p></div>
 </div>
</template>
<style scoped>
.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-left:1px solid var(--ui-border);border-top:1px solid var(--ui-border);border-radius:10px;overflow:hidden}.calendar-weekday{padding:.6rem;text-align:center;font-size:.7rem;color:var(--ui-text-muted);border-right:1px solid var(--ui-border);border-bottom:1px solid var(--ui-border)}.calendar-cell{min-height:120px;padding:.5rem;border-right:1px solid var(--ui-border);border-bottom:1px solid var(--ui-border);text-align:left;display:flex;flex-direction:column;gap:4px;overflow:hidden}.calendar-outside{color:var(--ui-text-muted);background:var(--ui-bg)}.calendar-selected{box-shadow:inset 0 0 0 2px var(--ui-primary)}.calendar-date{font-size:.75rem;width:26px;height:26px;display:grid;place-items:center;border-radius:50%}.calendar-today{background:var(--ui-primary);color:white}.calendar-event{display:block;max-width:100%;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;border-radius:4px;padding:3px 6px;font-size:.7rem}.calendar-activity{background:#0071e318;color:var(--ui-primary)}.calendar-renewal{background:#f59e0b20;color:#996000}.calendar-intention{background:#a855f720;color:#9851b5}@media(max-width:640px){.calendar-cell{min-height:70px;padding:3px}.calendar-event{font-size:.6rem;padding:2px}.calendar-weekday{padding:.5rem .1rem}}
</style>
